import java.util.ArrayList;
import java.util.List;

class AutoboxingDemo {
    public static void main(String[] args) {
        List<Integer> scores = new ArrayList<>();
        scores.add(90);          // autoboxing: int -> Integer
        scores.add(85);

        int first = scores.get(0); // unboxing: Integer -> int
        System.out.println("first = " + first);
    }
}

class StringPoolDemo {
    public static void main(String[] args) {
        String a = "hello";
        String b = "hello";           // lấy lại tham chiếu trong pool
        String c = new String("hello"); // đối tượng mới trên heap

        System.out.println(a == b);        // true: cùng tham chiếu pool
        System.out.println(a == c);        // false: khác vùng nhớ
        System.out.println(a.equals(c));   // true: so sánh nội dung
        System.out.println(a == c.intern()); // true: c.intern() trả tham chiếu pool
    }
}

